import{_ as s,o as a,c as t,a0 as i}from"./chunks/framework.l1I-fhud.js";const k=JSON.parse('{"title":"How to write a content driver","description":"","frontmatter":{},"headers":[],"relativePath":"how-to/write-a-driver.md","filePath":"how-to/write-a-driver.md"}'),n={name:"how-to/write-a-driver.md"};function r(o,e,l,h,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="how-to-write-a-content-driver" tabindex="-1">How to write a content driver <a class="header-anchor" href="#how-to-write-a-content-driver" aria-label="Permalink to &quot;How to write a content driver&quot;">​</a></h1><p>A <strong>driver</strong> teaches tamias how a content <em>type</em> installs, deploys, and uninstalls — with <strong>no compile-time coupling</strong>. tamias discovers <code>tamias-driver-&lt;type&gt;</code> on <code>PATH</code> or <code>&lt;tamias-home&gt;/drivers/</code> and runs it as a subprocess.</p><h2 id="the-contract" tabindex="-1">The contract <a class="header-anchor" href="#the-contract" aria-label="Permalink to &quot;The contract&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tamias-driver-&lt;type&gt; &lt;verb&gt; --dir &lt;dir&gt; --name &lt;name&gt; [--config &lt;file&gt;]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>verb</th><th>Meaning</th></tr></thead><tbody><tr><td><code>install</code></td><td>materialize the payload at <code>--dir</code></td></tr><tr><td><code>deploy</code></td><td>activate (unit, hooks)</td></tr><tr><td><code>uninstall</code></td><td>tear down</td></tr><tr><td><code>capabilities</code></td><td>print <code>{&quot;types&quot;:[…],&quot;verbs&quot;:[…]}</code> on stdout — the types + verbs this binary handles</td></tr></tbody></table><h2 id="ops-verbs-beyond-the-lifecycle-three" tabindex="-1">Ops verbs beyond the lifecycle three <a class="header-anchor" href="#ops-verbs-beyond-the-lifecycle-three" aria-label="Permalink to &quot;Ops verbs beyond the lifecycle three&quot;">​</a></h2><p><code>install</code>/<code>deploy</code>/<code>uninstall</code> are the only verbs tamias dispatches on its own. A driver may declare <strong>provider ops verbs</strong> — <code>health</code>, <code>status</code>, <code>hooks register</code>, anything the product needs — by listing them in <code>capabilities.verbs</code>; the operator reaches them through the generic passthrough:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> driver</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pk</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">g</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ver</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [args…]</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># → tamias-driver-&lt;type&gt; &lt;verb&gt; --dir &lt;dir&gt; --name &lt;name&gt; [--config &lt;f&gt;] [args…]</span></span></code></pre></div><p>Everything after <code>&lt;verb&gt;</code> lands verbatim as trailing argv, so verbs can take their own flags (<code>--dry-run</code>, <code>--api-base</code>, …). The driver&#39;s stdout/stderr stream back — status/probe verbs should print JSON or report lines. <code>tamias drivers --json</code> shows each driver&#39;s declared verbs; <code>tamias driver exec</code> warns (but still dispatches) when the verb isn&#39;t declared — the driver stays the authority. Provider verbs that answer with data are the right place for forge-hook registration, health probes, and unit status; <code>tamias run</code> remains local service exec only.</p><p><code>--config</code> is an optional path to a node/config file carrying operator params (<code>tamias deploy --config</code>). Exit zero on success; a non-zero exit fails the tamias verb, with your stderr surfaced. Dispatch has a 120s timeout (<code>capabilities</code> probes get 10s), so a hung driver fails the verb instead of wedging it.</p><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><p>tamias maps a package&#39;s <code>type:</code> to a driver. Naming the binary <code>tamias-driver-&lt;type&gt;</code> is enough — tamias tries that name first. A differently-named binary can still claim types by answering <code>capabilities</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$1</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capabilities ]; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;types&quot;:[&quot;myco-config&quot;]}&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  exit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># …handle install/deploy/uninstall…</span></span></code></pre></div><h2 id="ship-it-with-the-payload" tabindex="-1">Ship it with the payload <a class="header-anchor" href="#ship-it-with-the-payload" aria-label="Permalink to &quot;Ship it with the payload&quot;">​</a></h2><p>Drop the binary under <code>drivers/</code> in your payload — but know that this makes the package <strong>self-modifying</strong>: a bundled driver is arbitrary code that runs on the installer&#39;s machine. tamias therefore gates it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-drivers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">re</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">f</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or export TAMIAS_ALLOW_DRIVERS=1 once</span></span></code></pre></div><p>Without consent the install <strong>fails before anything is registered or executed</strong> — no partial store entry, no copied driver. Only regular files directly under <code>drivers/</code> are registered, into <code>&lt;tamias-home&gt;/drivers/</code>, where tamias discovers them.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mypkg/</span></span>
<span class="line"><span>  tamias.yaml         # type: myco-config</span></span>
<span class="line"><span>  drivers/</span></span>
<span class="line"><span>    tamias-driver-myco</span></span></code></pre></div><h2 id="what-if-there-s-no-driver" tabindex="-1">What if there&#39;s no driver? <a class="header-anchor" href="#what-if-there-s-no-driver" aria-label="Permalink to &quot;What if there&#39;s no driver?&quot;">​</a></h2><p>A package whose <code>type:</code> has no discoverable driver <strong>fails to install</strong> (any type other than <code>files</code>). tamias never silently &quot;installs&quot; content it can&#39;t place — so either ship the driver, publish <code>tamias-driver-&lt;type&gt;</code> on the host&#39;s <code>PATH</code>, or use <code>type: files</code>.</p><p><code>tamias deploy</code>/<code>uninstall</code> behave the same way: they dispatch to the driver for the package&#39;s type and warn when none exists.</p><h2 id="trust-boundary" tabindex="-1">Trust boundary <a class="header-anchor" href="#trust-boundary" aria-label="Permalink to &quot;Trust boundary&quot;">​</a></h2><p>Your driver binary runs with <strong>full user privileges</strong> over an <strong>untrusted <code>--dir</code> payload</strong> — the payload came from a package ref you may not control. Treat everything under <code>--dir</code> as hostile:</p><ul><li><strong>Never execute payload files yourself.</strong> If the payload ships a script or binary, running it is the payload&#39;s privilege escalation, not yours.</li><li><strong>Validate every path</strong> you read or write — reject <code>..</code> traversal, absolute paths, and symlink escapes before touching the filesystem.</li><li><strong>Don&#39;t trust manifest-declared paths or names</strong> — a manifest is package-controlled data, not an instruction from the operator.</li></ul><p>The consent gates (<code>--allow-drivers</code> / <code>TAMIAS_ALLOW_DRIVERS=1</code> / per-package consent memory) decide whether tamias <em>registers</em> a bundled driver — they are <strong>not a sandbox</strong>. Your driver is the last line of defense.</p><h2 id="check" tabindex="-1">Check <a class="header-anchor" href="#check" aria-label="Permalink to &quot;Check&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # every discovered driver + its capabilities</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drivers</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # same, machine-readable</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # lists discovered drivers among the health checks</span></span></code></pre></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/tamias/explanation/content-types.html">Content types</a></li><li><a href="/tamias/how-to/provision-a-service.html">Provision and service</a></li></ul>`,29)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
